#include <iostream>
#include <random>
#include <vector>
#include <stdexcept>

struct Plan {
    int semilla;
    int cantidad;
    int minimo;
    int maximo;
};

bool plan_valido(const Plan& plan) {
    return plan.semilla >= 0 && plan.semilla <= 1000
        && plan.cantidad >= 0 && plan.cantidad <= 20
        && plan.minimo >= 0 && plan.minimo <= 9
        && plan.maximo >= 0 && plan.maximo <= 9
        && plan.minimo <= plan.maximo;
}

std::vector<int> preparar(const Plan& plan) {
    if (!plan_valido(plan)) {
        throw std::invalid_argument("Plan invalido");
    }
    std::mt19937 motor{static_cast<std::mt19937::result_type>(plan.semilla)};
    std::uniform_int_distribution<int> elegir{plan.minimo, plan.maximo};
    std::vector<int> datos;
    for (int i{0}; i < plan.cantidad; ++i) {
        datos.push_back(elegir(motor));
    }
    return datos;
}

struct Informe {
    int cantidad;
    int menores;
    int desde;
    bool en_rango;
};

Informe resumir(const std::vector<int>& datos, int minimo, int maximo,
                int umbral) {
    if (datos.size() > 20 || minimo < 0 || minimo > 9
            || maximo < 0 || maximo > 9 || minimo > maximo
            || umbral < 0 || umbral > 9) {
        throw std::invalid_argument("Resumen invalido");
    }
    int menores{0};
    int desde{0};
    bool en_rango = true;
    for (int dato : datos) {
        en_rango = en_rango && dato >= minimo && dato <= maximo;
        if (dato < umbral) { ++menores; }
        else { ++desde; }
    }
    return Informe{static_cast<int>(datos.size()), menores, desde, en_rango};
}

int main() {
    const Plan plan{271, 12, 1, 7};
    try {
        const std::vector<int> primera = preparar(plan);
        const std::vector<int> segunda = preparar(plan);
        const Informe informe = resumir(primera, plan.minimo, plan.maximo, 4);
        std::cout << "Cantidad:" << informe.cantidad << '\n';
        std::cout << "Rango:" << informe.en_rango << '\n';
        std::cout << "Conteo:" << (informe.menores + informe.desde == informe.cantidad) << '\n';
        std::cout << "Repeticion:" << (primera == segunda);
    } catch (const std::invalid_argument&) {
        std::cout << "Configuracion rechazada";
    }
    return 0;
}

