#include <iostream>
#include <random>
#include <vector>
#include <stdexcept>

std::vector<int> frecuencias(const std::vector<int>& datos) {
    if (datos.size() > 20) {
        throw std::invalid_argument("Demasiados datos");
    }
    for (int dato : datos) {
        if (dato < 0 || dato > 9) {
            throw std::invalid_argument("Dato fuera de rango");
        }
    }
    std::vector<int> tabla(10);
    for (int dato : datos) {
        tabla.at(dato) += 1;
    }
    return tabla;
}

int main() {
    const std::vector<int> datos{2, 0, 2, 9};
    const std::vector<int> original = datos;
    try {
        const std::vector<int> tabla = frecuencias(datos);
        int total{0};
        for (int i{0}; i < 10; ++i) {
            total += tabla[i];
            if (tabla[i] != 0) {
                std::cout << i << ':' << tabla[i] << '\n';
            }
        }
        std::cout << "Total:" << total << '\n';
        std::cout << "Conservado:" << (datos == original);
    } catch (const std::invalid_argument&) {
        std::cout << "Datos rechazados";
    }
    return 0;
}
